import java.io.Serializable;

/**
 * Google cluster-data task event.
 *
 * CSV columns (13): timestamp,missingInfo,jobId,taskIndex,machineId,
 * eventType,userName,schedulingClass,priority,cpuReq,memReq,diskReq,machineConstraint
 * Timestamps are microseconds since trace start.
 */
public class TaskEvent implements Serializable {

    public static final int SUBMIT = 0;

    public long timestamp;
    public long jobId;
    public long taskIndex;
    public int eventType;

    public TaskEvent() {}

    public TaskEvent(long timestamp, long jobId, long taskIndex, int eventType) {
        this.timestamp = timestamp;
        this.jobId = jobId;
        this.taskIndex = taskIndex;
        this.eventType = eventType;
    }

    public static TaskEvent fromCsv(String line) {
        String[] f = line.split(",", -1);
        TaskEvent e = new TaskEvent();
        e.timestamp = parseLong(f[0]);
        e.jobId = parseLong(f[2]);
        e.taskIndex = parseLong(f[3]);
        e.eventType = parseInt(f[5]);
        return e;
    }

    /** Returns event time in milliseconds (input is microseconds). */
    public long eventTimeMillis() {
        return timestamp / 1000L;
    }

    private static long parseLong(String s) {
        return (s == null || s.isEmpty()) ? 0L : Long.parseLong(s);
    }

    private static int parseInt(String s) {
        return (s == null || s.isEmpty()) ? 0 : Integer.parseInt(s);
    }

    @Override
    public String toString() {
        return "TaskEvent{ts=" + timestamp + ",jobId=" + jobId
                + ",taskIndex=" + taskIndex + ",type=" + eventType + "}";
    }
}
