    }

    private static int parseInt(String s) {
        return (s == null || s.isEmpty()) ? 0 : Integer.parseInt(s);
    }

    @Override
    public String toString() {
        return "JobEvent{ts=" + timestamp + ",jobId=" + jobId + ",type=" + eventType + "}";
