import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import org.apache.flink.streaming.api.functions.source.SourceFunction;

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.zip.GZIPInputStream;

/**
 * Simple bounded SourceFunctions that read gzipped CSV files and emit
 * {@link TaskEvent} or {@link JobEvent} records. Flink's default file source
 * does not transparently decompress .gz in a portable way, so we wrap the
 * FileInputStream in a GZIPInputStream manually.
 */
public class GzipCsvSources {

    public static SourceFunction<TaskEvent> taskEventSource(String path) {
        return new SourceFunction<TaskEvent>() {
            private volatile boolean running = true;

            @Override
            public void run(SourceContext<TaskEvent> ctx) throws Exception {
                try (BufferedReader r = openGz(path)) {
                    String line;
                    while (running && (line = r.readLine()) != null) {
                        if (line.isEmpty()) continue;
                        ctx.collect(TaskEvent.fromCsv(line));
                    }
                }
            }

            @Override
            public void cancel() {
                running = false;
            }
        };
    }

    public static SourceFunction<JobEvent> jobEventSource(String path) {
        return new SourceFunction<JobEvent>() {
            private volatile boolean running = true;

            @Override
            public void run(SourceContext<JobEvent> ctx) throws Exception {
                try (BufferedReader r = openGz(path)) {
                    String line;
                    while (running && (line = r.readLine()) != null) {
                        if (line.isEmpty()) continue;
                        ctx.collect(JobEvent.fromCsv(line));
                    }
                }
            }

            @Override
            public void cancel() {
                running = false;
            }
        };
    }

    private static BufferedReader openGz(String path) throws Exception {
        return new BufferedReader(new InputStreamReader(
                new GZIPInputStream(new FileInputStream(path)), StandardCharsets.UTF_8));
    }
}
