"""Reference implementation of longest SUBMIT-event session per finished job."""
import gzip, csv, sys
from collections import defaultdict

TASK = sys.argv[1]
JOB = sys.argv[2]
OUT = sys.argv[3]
GAP_SEC = 600  # 10 minutes

# 1) Determine which jobs finished (FINISH/FAIL/KILL/LOST = 4/3/5/6)
finished = set()
with gzip.open(JOB, "rt") as f:
    for row in csv.reader(f):
        try:
            jid = int(row[2])
            et = int(row[3])
        except Exception:
            continue
        if et in (3, 4, 5, 6):
            finished.add(jid)

# 2) Collect SUBMIT (eventType == 0) task events per job
submits = defaultdict(list)  # jobId -> list of event-time microseconds
with gzip.open(TASK, "rt") as f:
    for row in csv.reader(f):
        try:
            ts = int(row[0])
            jid = int(row[2])
            et = int(row[5])
        except Exception:
            continue
        if et == 0:
            submits[jid].append(ts)

# 3) For each finished job, sort SUBMIT times and find longest session by count
gap_us = GAP_SEC * 1_000_000
results = {}
for jid, times in submits.items():
    if jid not in finished:
        continue
    times.sort()
    best = cur = 0
    prev = None
    for t in times:
        if prev is None or (t - prev) < gap_us:
            cur += 1
        else:
            if cur > best:
                best = cur
            cur = 1
        prev = t
    if cur > best:
        best = cur
    results[jid] = best

